    enonce: "<span dir=\"ltr\" class=\"expr pt\">M</span> حجر منتصب <span dir=\"ltr\" class=\"expr\">(</span>منهير<span dir=\"ltr\" class=\"expr\">)</span> يتعذّر الوصول إليه.<br>النّقط <span dir=\"ltr\" class=\"expr pt\">M</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> و <span dir=\"ltr\" class=\"expr pt\">A</span> على استقامة واحدة، و كذلك <span dir=\"ltr\" class=\"expr pt\">M</span> و <span dir=\"ltr\" class=\"expr pt\">D</span> و <span dir=\"ltr\" class=\"expr pt\">B</span>،<br>و <span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span> حيث <span dir=\"ltr\" class=\"expr pt\">CD = 71,4 m</span> و <span dir=\"ltr\" class=\"expr pt\">AB = 142,8 m</span> و <span dir=\"ltr\" class=\"expr pt\">CA = 88,2 m.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 287 144\" width=\"287\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(18.4 21.7)\"><line x1=\"6.7\" y1=\"96.8\" x2=\"243.3\" y2=\"96.8\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"6.7\" y1=\"96.8\" x2=\"74.3\" y2=\"6.7\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"243.3\" y1=\"96.8\" x2=\"74.3\" y2=\"6.7\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"125.0\" y1=\"96.8\" x2=\"40.5\" y2=\"51.8\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><circle cx=\"6.7\" cy=\"96.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"-7.7\" y=\"105.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">M</text><circle cx=\"243.3\" cy=\"96.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"258.0\" y=\"103.6\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"74.3\" cy=\"6.7\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"69.0\" y=\"-3.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"125.0\" cy=\"96.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"135.6\" y=\"111.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text><circle cx=\"40.5\" cy=\"51.8\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"26.2\" y=\"51.3\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">D</text></g></svg><br><span dir=\"ltr\" class=\"expr\">1)</span> أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">CM.</span><br><span dir=\"ltr\" class=\"expr\">2)</span> استنتج المسافة <span dir=\"ltr\" class=\"expr pt\">AM.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">CD = 71,4</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 142,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 88,2</span>  و  <span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>"},{"quoi":"1)","math":"أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">CM.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">CM.</span> نختار النّسبة و الجزء الباقي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">357</span><span class=\"den\">5</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">AB =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">714</span><span class=\"den\">5</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">AC =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">441</span><span class=\"den\">5</span></span>. و لماذا لا نظرية بيتاغور ؟ لأنّها تحتاج مثلّثا قائم الزاوية، و لا نعرف زاوية قائمة في هذا الشّكل."},{"quoi":"في المثلّث MAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MD</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CD</span><span class=\"den\">AB</span></span>"},{"quoi":"القاعدة","math":"إذا عُلمت النّسبة و عُلم الجزء الباقي، أمكن حساب الطولين"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD = 71,4</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 142,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 88,2</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CM =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">441</span><span class=\"den\">5</span></span>  ، لأنّ النّسبة <span class=\"frac\" dir=\"ltr\"><span class=\"num\">71,4</span><span class=\"den\">142,8</span></span> و الفرق 88,2"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CM = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">441</span><span class=\"den\">5</span></span>"},{"quoi":"2)","math":"استنتج المسافة <span dir=\"ltr\" class=\"expr pt\">AM.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AM.</span> نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">CD =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">357</span><span class=\"den\">5</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">AB =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">714</span><span class=\"den\">5</span></span>  و  <span dir=\"ltr\" class=\"expr pt\">CM =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">441</span><span class=\"den\">5</span></span>. و لماذا لا نظرية بيتاغور ؟ لأنّها تحتاج مثلّثا قائم الزاوية، و لا نعرف زاوية قائمة في هذا الشّكل."},{"quoi":"في المثلّث MAB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(CD) // (AB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (MA)</span>  و  <span dir=\"ltr\" class=\"expr pt\">D ∈ (MB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">MC</span><span class=\"den\">MA</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MD</span><span class=\"den\">MB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">CD</span><span class=\"den\">AB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">71,4</span><span class=\"den\">142,8</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\"><span class=\"frac\" dir=\"ltr\"><span class=\"num\">441</span><span class=\"den\">5</span></span><span dir=\"ltr\" class=\"expr pt\">&lt;/span&gt;&lt;span class=\"den\"&gt;AM&lt;/span&gt;&lt;/span&gt;</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AM = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">882</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AM = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">882</span><span class=\"den\">5</span></span>"}],
